from collections import deque
graph = {"A": ["B", "C"], "B": ["E"], "C": ["D"], "D": ["E"], "E": ["F"], "F": []}

def bfs(start):
    dist = {start: 0}
    q = deque([start])
    while q:
        node = q.popleft()
        for nb in graph[node]:
            if nb not in dist:
                dist[nb] = dist[node] + 1
                q.append(nb)
    return dist

print(bfs("A"))

graph = {1: [2, 3], 2: [4], 3: [4], 4: [1]}

def dfs(start):
    seen, stack, order = set(), [start], []
    while stack:
        node = stack.pop()
        if node in seen:
            continue
        seen.add(node)
        order.append(node)
        for nb in graph[node]:
            stack.append(nb)
    return order

print(dfs(1))

